36	const componentGroupBase = (count: number): number =>
37	  count === COMPONENT_BLOCK_SIZE
38	    ? COMPONENT_BLOCK_PREMIUM
39	    : count * COMPONENT_BASE_PREMIUM;
40	
41	const itemBasePremiums = (items: Item[]): number[] => {
42	  const bases: number[] = [];
43	  const componentCounts = new Map<string, number>();
44	  for (const item of items) {
45	    if (COMPONENT_TYPES.has(item.type)) {
46	      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
47	    } else {
48	      bases.push(BASE_PREMIUMS[item.type]);
49	    }
50	  }
51	  for (const count of componentCounts.values()) {
52	    bases.push(componentGroupBase(count));
53	  }
54	  return bases;
55	};
56	
57	const quotePremium = (items: Item[]): number => {
58	  const bases = itemBasePremiums(items);
59	  const itemsTotal = bases.reduce(
60	    (sum, base) => sum + base + base * FIRST_INSURANCE_SURCHARGE,
61	    0,
62	  );
63	  return Math.ceil(itemsTotal + PROCESSING_FEE);
64	};
65	
66	export const runScenario = (scenario: Scenario): ScenarioResult => {
67	  const results = scenario.steps.map((step) => ({ premium: quotePremium(step.items) }));
68	  return { results };
69	};
