const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const itemBasePremiums = (items: Item[]): number[] => {
  const mainItems = items.filter((item) => !COMPONENT_TYPES.has(item.type));
  const components = items.filter((item) => COMPONENT_TYPES.has(item.type));

  const mainBases = mainItems.map((item) => BASE_PREMIUMS[item.type]);
  const componentBases = [...countByType(components).values()].map(
    componentGroupBase,
  );

  return [...mainBases, ...componentBases];
};

